    },
    {
      "id": "future-projections",
      "title": "Future Projections Under Different Scenarios",
      "objective": "Illustrate how global warming trajectories differ across SSP scenarios and what each pathway means for temperature, sea level, and extreme events."
    },
    {
      "id": "risks-and-impacts",
      "title": "Risks, Vulnerabilities, and Cascading Impacts",
      "objective": "Highlight the disproportionate risks to vulnerable populations and ecosystems, and the compounding nature of climate hazards."
    },
    {
      "id": "mitigation-pathways",
      "title": "Mitigation and Adaptation Pathways",
      "objective": "Summarize the emissions reduction requirements to limit warming to 1.5°C and 2°C, and outline key adaptation strategies."
    },
    {
      "id": "call-to-action",
      "title": "The Narrowing Window for Action",
      "objective": "Convey the urgency of immediate, deep, and sustained action across all sectors and scales to secure a liveable future."
