const puppeteer = require('puppeteer');
const path = require('path');
const fs = require('fs');

(async () => {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();

  const htmlPath = path.resolve('/app/ipcc-ar6-poster.html');
  await page.goto('file://' + htmlPath, { waitUntil: 'networkidle0' });

  // Wait for fonts and rendering
  await page.evaluate(() => document.fonts.ready);
  await new Promise(r => setTimeout(r, 2000));

  // Get page dimensions
  const dimensions = await page.evaluate(() => {
    const body = document.body;
    return {
      width: Math.max(body.scrollWidth, 993),
      height: Math.max(body.scrollHeight, 1404)
    };
  });

  await page.setViewport({ width: dimensions.width, height: dimensions.height });

  // Wait again after viewport change
  await new Promise(r => setTimeout(r, 500));

  const outputPath = '/app/output/final_poster.png';
  await page.screenshot({
    path: outputPath,
    type: 'png',
    fullPage: true
  });

  console.log('Poster saved to:', outputPath);
  await browser.close();
})();
